	"face_liveness_introduction_disclaimer": "Aplikasi ini akan merakam dan menghantar foto kepada AWS secara ringkas, semata-mata untuk mengesahkan bahawa anda adalah orang sebenar dan bukan bot. Ia tidak akan dihantar ke X dan ia akan dipadamkan serta-merta selepas pengesahan oleh AWS. Ia tidak digunakan untuk sebarang tujuan selain daripada langkah anti-bot. Ia tidak akan dijual, dipajak atau diniagakan.",
