	"gift_premium_purchaser_terms": "Syarat Pembeli",
	"gift_premium_subtitle": "Beri hadiah %1$s untuk setahun kepada %2$s pada harga %3$s. Setelah anda melengkapkan pembayaran, mereka akan dimaklumkan bahawa anda telah menghantar hadiah kepada mereka.",
	"gift_premium_terms_footer": "Harga hadiah langganan dikenakan caj semasa pembelian dan tidak akan dibayar balik. Ini merupakan penggunaan satu kali, tidak boleh diganti, tidak boleh digabungkan, dan tidak memiliki nilai tunai. Hadiah langganan ini bermula selepas semakan X dan penugasan kepada penerima, yang mesti memperakui %1$s dan dasar kami. Jika penerima gagal untuk memenuhi mana-mana syarat kelayakan, membatalkan langganan atau menolak terma dan dasar kami, maka hadiah itu tidak boleh ditebus dan tidak akan dibayar balik. Cukai mungkin dikenakan. Terma boleh berubah. %2$s",
