	"go_to_twitter": "Pergi ke x.com",
	"golive__tip_broadcaster_1": "<b>PETUA:</b> Terima kasih kerana bersiaran langsung! Alu-alukan penonton dengan mengucapkan \\\"hai\\\" kepada mereka apabila mereka menyertai video anda.",
	"golive__tip_broadcaster_10": "<b>PETUA:</b> Terima kasih kerana bersiaran langsung di X! ≺3",
	"golive__tip_broadcaster_2": "<b>PETUA:</b> Cuba sebutkan seseorang dengan nama apabila mereka menyertai video langsung anda — mereka akan berasa seronok!",
	"golive__tip_broadcaster_3": "<b>PETUA:</b> Pastikan anda bersiaran langsung sekurang-kurangnya selama beberapa minit untuk memudahkan lagi orang mencari anda.",
	"golive__tip_broadcaster_4": "<b>PETUA:</b> Tanya penonton anda tentang tempat asal mereka — ini cara yang baik untuk beramah mesra.",
	"golive__tip_broadcaster_5": "<b>PETUA:</b> Ucapkan terima kasih kepada orang yang menonton dan balas komen mereka supaya mereka terus menonton.",
	"golive__tip_broadcaster_6": "<b>PETUA:</b> Jika anda kehilangan sambungan anda semasa bersiaran langsung, pergi ke tempat lain yang menyediakan isyarat yang lebih baik.",
	"golive__tip_broadcaster_7": "<b>PETUA:</b> Minta orang agar mengikuti anda supaya mereka menerima pemberitahuan apabila anda bersiaran langsung pada masa yang lain.",
	"golive__tip_broadcaster_8": "<b>PETUA:</b> Mulakan video langsung anda dengan terus mengucapkan \\\"hai\\\". Orang yang menonton selepas itu akan berasa suka.",
	"golive__tip_broadcaster_9": "<b>PETUA:</b> Ucapkan terima kasih kepada orang yang menonton sebelum anda menamatkan video langsung anda.",
