	"golive__tip_pre_broadcast_2": "<b>PETUA:</b> Tajuk yang deskriptif dapat membantu orang agar lebih memahami tentang topik video langsung anda.",
	"golive__tip_pre_broadcast_3": "<b>PETUA:</b> Perlukan idea? Buat lawatan, kongsi bakat atau bercakap tentang perkara yang anda minati.",
	"golive__tip_pre_broadcast_4": "<b>PETUA:</b> Pastikan anda mempunyai isyarat telefon yang kuat sebelum bersiaran langsung.",
	"golive__tip_pre_broadcast_5": "<b>PETUA:</b> Tambahkan hashtag pada tajuk anda untuk membantu orang menemui video langsung anda.",
	"golive__tip_pre_broadcast_6": "<b>PETUA:</b> Itu sahaja petua yang kami ada buat masa ini — terima kasih kerana bersiaran langsung di X!",
