	"identity_education_cancel": "Langkau buat Masa ini",
	"identity_education_conditions": "Saya mengizinkan X dan Au10tix untuk menggunakan imej ID saya dan swafoto saya, termasuk data biometrik yang diekstrak, bagi mengesahkan identiti saya dan bagi tujuan keselamatan dan perlindungan yang berkaitan dengan X, termasuk untuk mencegah penyamaran. Au10tix boleh menyimpan data tersebut sehingga tempoh 30 hari. {{}}Ketahui lebih lanjut{{}}",
	"identity_education_conditions_age_verification": "Saya bersetuju dengan X dan Persona untuk menggunakan ID saya dan foto saya bagi mengesahkan umur saya. Foto anda tidak akan disimpan. X dan xAI mungkin akan menyimpan maklumat umur anda. {{}}Ketahui lebih lanjut{{}}",
	"identity_education_conditions_eea": "\"Saya mengizinkan X untuk berkongsi imej ID saya, termasuk data biometrik, dan data peribadi daripada profil saya dengan Au10tix bagi tujuan pengesahan identiti saya.\nSaya juga mengizinkan X untuk menyimpan imej ID saya, termasuk data biometrik, sehingga tempoh 30 hari dan menggunakan data tersebut dan data daripada profil saya bagi tujuan keselamatan dan perlindungan, termasuk untuk mencegah penyamaran. {{}}Ketahui lebih lanjut{{}}\"",
	"identity_education_conditions_persona_vendor": "Saya bersetuju dengan X dan Persona untuk menggunakan imej ID saya dan swafoto saya, termasuk data biometrik yang diekstrak, untuk mengesahkan identiti saya dan bagi tujuan keselamatan dan perlindungan yang berkaitan dengan X, pencegahan penipuan dan pembayaran. Persona boleh menyimpan data tersebut sehingga tempoh 30 hari. X boleh menyimpan nama penuh, alamat, dan cincangan nombor ID dokumen saya selagi saya melanggan perkhidmatan X Premium. {{}}Ketahui lebih lanjut{{}}",
