	"profile_smart_blocked_autoblocked_by_twitter_description": "\"Anda telah disekat secara automatik buat sementara waktu daripada melihat dan berinteraksi dengan siaran @%1$s. Ini berlaku apabila mereka berada dalam Mod Keselamatan dan kami menandai interaksi anda sebagai mungkin bersifat penyalahgunaan atau spam.\n\nKami sedar bahawa tindakan sekatan secara automatik kami mungkin tidak tepat pada setiap masa. Oleh itu, kami akan terus meningkatkan pengesanan kami.\n\n{{}}Apakah itu%2$sMod%2$sKeselamatan?{{}}\n\nBerikut ialah cara untuk mengekalkan perbualan yang sihat — dan mengelakkan daripada disekat secara automatik.\"",
