	"ps__tip_broadcaster_1": "<b>PETUA:</b> Terima kasih kerana bersiaran! Pastikan anda mengucapkan hai kepada penonton apabila mereka menyertai siaran.",
	"ps__tip_broadcaster_11": "<b>PETUA:</b> Terima kasih kerana bersiaran di Periscope! ≺3",
	"ps__tip_broadcaster_2": "<b>PETUA:</b> Cuba sebutkan nama penonton yang menyertai siaran anda; pasti mereka berasa seronok!",
	"ps__tip_broadcaster_3": "<b>PETUA:</b> Pastikan anda bersiaran selama sekurang-kurangnya beberapa minit untuk memudahkan orang lain menemui anda.",
	"ps__tip_broadcaster_4": "<b>PETUA:</b> Antara cara yang bagus untuk memupuk kemesraan dengan penonton anda ialah dengan menanyakan tempat asal mereka.",
	"ps__tip_broadcaster_5": "<b>PETUA:</b> Ucapkan terima kasih kepada penonton kerana menonton dan balas komen mereka supaya mereka terus berinteraksi.",
	"ps__tip_broadcaster_6": "<b>PETUA:</b> Jika anda kehilangan sambungan semasa bersiaran, pergi ke tempat lain yang menyediakan isyarat yang lebih baik.",
	"ps__tip_broadcaster_7": "<b>PETUA:</b> Minta penonton anda agar mengikuti anda supaya mereka menerima pemberitahuan apabila anda bersiaran langsung.",
	"ps__tip_broadcaster_8": "<b>PETUA:</b> Mulakan siaran anda dengan terus mengucapkan hai. Penonton ulang main anda akan menyukainya.",
	"ps__tip_broadcaster_9": "<b>PETUA:</b> Ucapkan terima kasih kepada penonton anda kerana menonton, sebelum anda menamatkan siaran anda.",
	"ps__tip_pre_broadcast_1": "<b>PETUA:</b> Tulis tajuk sebelum memulakan siaran anda dan temui orang yang mempunyai minat yang sama.",
	"ps__tip_pre_broadcast_2": "<b>PETUA:</b> Tajuk yang deskriptif dapat membantu penonton memahami topik siaran anda.",
	"ps__tip_pre_broadcast_3": "<b>PETUA:</b> Anda perlukan idea? Buat lawatan, kongsi bakat atau bercakap tentang topik yang anda minati.",
	"ps__tip_pre_broadcast_4": "<b>PETUA:</b> Pastikan anda mempunyai isyarat telefon yang kuat sebelum bersiaran langsung.",
	"ps__tip_pre_broadcast_5": "<b>PETUA:</b> Kongsi siaran anda di X untuk menjangkau lebih ramai penonton.",
	"ps__tip_pre_broadcast_6": "<b>PETUA:</b> Jika anda mengikuti orang yang mengikuti anda kembali, anda boleh menyiarkan secara peribadi kepada mereka.",
	"ps__tip_pre_broadcast_8": "<b>PETUA:</b> Tambahkan hashtag yang berkaitan pada tajuk anda untuk membantu orang menemui siaran anda.",
	"ps__tip_pre_broadcast_9": "<b>PETUA:</b> Itu sahaja petua yang kami ada buat masa ini. Terima kasih kerana menggunakan Periscope!",
