	"room_settings_clips": "Klip",
	"room_settings_clips_description": "\"Apabila anda membuat klip, klip tersebut akan merakamkan audio bagi 30 saat yang lalu. \n \nSebagai hos, anda boleh memadamkan klip Space anda yang dibuat oleh orang lain. Namun, jika anda memadamkan satu klip daripada Space anda, semua klip daripada Space yang sama itu akan turut dipadamkan. \n \nJika anda merakamkan Space, kemudian memadamkan Space itu, mana-mana klip daripada Space tersebut akan turut dipadamkan. \n \nSemua klip akan tamat tempoh selepas 30 hari.\"",
