	"safety_mode_settings_half_sheet_description_1": "Apabila kami mengesan balasan, sebutan atau petikan yang mungkin bersifat penyalahgunaan atau spam, kami akan menyekat akaun tersebut secara automatik buat sementara waktu. Sekatan secara automatik berlarutan selama seminggu dan ini berbeza dengan sekatan secara manual.",
	"safety_mode_settings_half_sheet_description_2": "Akaun yang disekat secara automatik, sama seperti akaun yang disekat secara manual, tidak dapat melihat siaran anda, mengikuti anda atau menghantar mesej kepada anda. Jika mereka melihat profil anda, kami akan memberitahu mereka bahawa X telah menyekat mereka secara automatik, bukannya anda.",
