	"tipjar_input_rationale_kakao_pay": "\"Orang akan menghantar tip kepada Pautan QR yang anda masukkan di atas.\nDengan menambahkan Pautan QR anda dan menerima tip, anda mungkin mendedahkan maklumat tentang diri anda yang dikongsi pada perkhidmatan bayaran tersebut, termasuk nama, alamat e-mel dan maklumat anda yang lain.\n\nPautan QR Kakao Pay boleh ditemui di KakaoTalk Lagi > Pengimbas di Penjuru Kanan Sebelah Atas > Kod Wang > Ikon imej Papan klip. Ketik ikon tersebut untuk menyalin pautan ke papan klip anda, kemudian tampalkan pautan di atas.\"",
